exercises.starter_code:
#include <stdio.h>

int main(void) {
    const char *fruits[] = {"apple", "banana", "cherry"};
    // len
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <stddef.h>

int main(void) {
    const char *fruits[] = {"apple", "banana", "cherry"};
    printf("%zu\n", sizeof fruits / sizeof fruits[0]);
    return 0;
}

